[{"order":1,"type":"heading","text":"Design Patterns: Structural (Adapter, Decorator, Facade)"},{"order":2,"type":"paragraph","text":"Structural design patterns in Object-Oriented Programming (OOP) explain how to assemble objects and classes into larger structures while keeping these structures flexible and efficient. This tutorial explores three fundamental structural patterns: Adapter, Decorator, and Facade."},{"order":3,"type":"heading","text":"1. The Adapter Pattern"},{"order":4,"type":"paragraph","text":"The Adapter pattern allows incompatible interfaces to work together. It acts as a bridge between two incompatible interfaces by wrapping an existing class with a new interface."},{"order":5,"type":"subheading","text":"Adapter Implementation Example"},{"order":6,"type":"code","text":"class Target {
    public function request(): string {
        return "Target: The default target's behavior.";
    }
}

class Adaptee {
    public function specificRequest(): string {
        return ".eetpadA eht fo roivaheb laicepS";
    }
}

class Adapter extends Target {
    private $adaptee;

    public function __construct(Adaptee $adaptee) {
        $this->adaptee = $adaptee;
    }

    public function request(): string {
        return "Adapter: (TRANSLATED) " . strrev($this->adaptee->specificRequest());
    }
}"},{"order":7,"type":"heading","text":"2. The Decorator Pattern"},{"order":8,"type":"paragraph","text":"The Decorator pattern lets you attach new behaviors to objects by placing these objects inside special wrapper objects that contain the behaviors. This provides a flexible alternative to subclassing for extending functionality."},{"order":9,"type":"subheading","text":"Decorator Implementation Example"},{"order":10,"type":"code","text":"interface Component {
    public function operation(): string;
}

class ConcreteComponent implements Component {
    public function operation(): string {
        return "ConcreteComponent";
    }
}

class Decorator implements Component {
    protected $component;

    public function __construct(Component $component) {
        $this->component = $component;
    }

    public function operation(): string {
        return $this->component->operation();
    }
}

class ConcreteDecoratorA extends Decorator {
    public function operation(): string {
        return "ConcreteDecoratorA(" . parent::operation() . ")";
    }
}"},{"order":11,"type":"heading","text":"3. The Facade Pattern"},{"order":12,"type":"paragraph","text":"The Facade pattern provides a simplified interface to a library, a framework, or any other complex set of classes. It shields clients from the complex subsystems underneath."},{"order":13,"type":"subheading","text":"Facade Implementation Example"},{"order":14,"type":"code","text":"class Subsystem1 {
    public function operation1(): string {
        return "Subsystem1: Ready!";
    }
}

class Subsystem2 {
    public function operationZ(): string {
        return "Subsystem2: Go!";
    }
}

class Facade {
    protected $subsystem1;
    protected $subsystem2;

    public function __construct(Subsystem1 $subsystem1, Subsystem2 $subsystem2) {
        $this->subsystem1 = $subsystem1;
        $this->subsystem2 = $subsystem2;
    }

    public function operation(): string {
        $result = "Facade initializes subsystems:\n";
        $result .= $this->subsystem1->operation1() . "\n";
        $result .= $this->subsystem2->operationZ();
        return $result;
    }
}"},{"order":15,"type":"heading","text":"Summary of Structural Patterns"},{"order":16,"type":"bullet_point","text":"Adapter: Makes incompatible interfaces compatible without altering source code."},{"order":17,"type":"bullet_point","text":"Decorator: Dynamically adds responsibilities to objects transparently."},{"order":18,"type":"bullet_point","text":"Facade: Simplifies interactions with complex subsystems by offering a unified high-level interface."}]
